[metadata] {"type": "create", "filePath": "/workspace/repo/ui/lib/findings-sort.ts", "content": "/**
 * Shared sort tokens and presets for the findings surfaces.
 *
 * This module is intentionally free of any server-only code (auth headers,
 * `next/navigation`, etc.) so action files, components, and hooks can import
 * the sort vocabulary via the `@/lib` barrel without pulling in the
 * server-action runtime.
 *
 * Two distinct families exist because the two APIs order differently:
 *
 *   Family A — plain findings. Backed by Postgres ENUM columns whose natural
 *   ascending order already puts FAIL/critical first. Ascending tokens
 *   (no minus prefix) are therefore correct for `status` and `severity`.
 *
 *   Family B — finding-groups. Backed by integer-weighted computed columns
 *   where higher weight = more severe/newer. Descending order (minus prefix)
 *   is required to put FAIL/critical/new results first.
 */

// ---------------------------------------------------------------------------
// Family A — plain findings (Postgres ENUM, ascending = FAIL/critical first)
// ---------------------------------------------------------------------------

/** FAIL results first. Ascending ENUM order — no minus prefix. */
export const FINDINGS_FAIL_FIRST = "status";
/** Most severe first. Ascending ENUM order — no minus prefix. */
export const FINDINGS_SEVERITY_HIGH_FIRST = "severity";
/** Most recently inserted first. */
export const FINDINGS_RECENT_INSERT = "-inserted_at";
/** Most recently updated first. */
export const FINDINGS_RECENT_UPDATE = "-updated_at";

// ---------------------------------------------------------------------------
// Family B — finding-groups (integer-weighted columns, descending = first)
// ---------------------------------------------------------------------------

/** FAIL groups first. Descending weight — minus prefix required. */
export const FG_FAIL_FIRST = "-status";
/** Most severe groups first. Descending weight — minus prefix required. */
export const FG_SEVERITY_HIGH_FIRST = "-severity";
/** Newly failing groups first. Descending weight — minus prefix required. */
export const FG_DELTA_NEW_FIRST = "-delta";
/** Most recently seen groups first. */
export const FG_RECENT_LAST_SEEN = "-last_seen_at";

// ---------------------------------------------------------------------------
// Preset composite sort strings — Family A (plain findings)
// ---------------------------------------------------------------------------

/**
 * Default plain-findings sort: FAIL first, then most severe, then most
 * recent. No `delta` — plain findings do not expose that field.
 */
export const FINDINGS_DEFAULT_SORT = "status,severity,-inserted_at";
/**
 * Plain-findings sort when the API call already applies `filter[status]`;
 * `status` is omitted from the sort because every row shares one status.
 */
export const FINDINGS_FILTERED_SORT = "severity,-inserted_at";
/**
 * "Other findings" list in the resource drawer. Uses `updated_at` because the
 * latest-findings endpoint exposes it (not `inserted_at`).
 */
export const RESOURCE_DRAWER_OTHER_FINDINGS_SORT = "severity,-updated_at";

// ---------------------------------------------------------------------------
// Preset composite sort strings — Family B (finding-groups)
// ---------------------------------------------------------------------------

/** Default finding-groups list sort. */
export const FINDING_GROUPS_DEFAULT_SORT =
  "-status,-severity,-delta,-last_seen_at";
/** Finding-group resources drill-down sort. Same shape as the groups list. */
export const FINDING_GROUP_RESOURCES_DEFAULT_SORT =
  "-status,-severity,-delta,-last_seen_at";
/**
 * Finding-groups sort when a status filter is already applied. Omits `status`
 * and `delta`; must NOT contain `inserted_at`, which is not a valid sort
 * parameter on the grouped API and would cause a backend error.
 */
export const FINDING_GROUPS_FILTERED_SORT = "-severity,-last_seen_at";

// ---------------------------------------------------------------------------
// Composition helper
// ---------------------------------------------------------------------------

/**
 * Joins sort token strings with commas, in the order given. The leftmost
 * token has the highest sort precedence (JSON:API rule). Returns an empty
 * string when called with no arguments.
 */
export function composeSort(...tokens: string[]): string {
  return tokens.join(",");
}
