/** Wire-format value the API expects for a failing-status filter. */
export const FAIL_FILTER_VALUE = "FAIL";

/** Wire-format value the API expects for a "newly failing" delta filter. */
export const NEW_DELTA_FILTER_VALUE = "new";

/**
 * Mutates `params` in place so the request asks the API only for failing,
 * non-muted findings. Any pre-existing values for `filter[status__in]` and
 * `filter[muted]` are overwritten; all other params are left untouched.
 */
export function applyFailNonMutedFilters(params: URLSearchParams): void {
  params.set("filter[status__in]", FAIL_FILTER_VALUE);
  params.set("filter[muted]", MUTED_FILTER.EXCLUDE);
