/**
 * Normalises a filter value into a flat array of non-empty, trimmed tokens.
 *
 * Returns `[]` for `undefined`. A single string is split on commas; an array
 * is flattened by splitting each element on commas. Tokens that are empty
 * after trimming (stray or trailing commas) are dropped.
 */
export function splitCsvFilterValues(
  value: string | string[] | undefined,
): string[] {
  if (Array.isArray(value)) {
    return value
      .flatMap((item) => item.split(","))
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return value
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean);
  }

  return [];
}

